  1→package testutil
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"errors"
  7→	"fmt"
  8→	"os"
  9→	"os/exec"
 10→	"path/filepath"
 11→	"strings"
 12→	"testing"
 13→	"time"
 14→
 15→	"github.com/entireio/cli/e2e/agents"
 16→	"github.com/entireio/cli/e2e/entire"
 17→)
 18→
 19→// RepoState holds the working state for a single test's cloned repository.
 20→type RepoState struct {
 21→	Agent            agents.Agent
 22→	Dir              string
 23→	ArtifactDir      string
 24→	HeadBefore       string
 25→	CheckpointBefore string
 26→	ConsoleLog       *os.File
 27→	session          agents.Session // interactive session, if started via StartSession
 28→}
 29→
 30→// SetupRepo creates a fresh git repository in a temporary directory, seeds it
 31→// with an initial commit, and runs `entire enable` for the given agent.
 32→// Artifact capture is registered as a cleanup function.
 33→//
 34→// When E2E_KEEP_REPOS is set, the temporary directory is not cleaned up
 35→// so it can be inspected after the test. A symlink in the artifact dir
 36→// points to the preserved repo.
 37→func SetupRepo(t *testing.T, agent agents.Agent) *RepoState {
 38→	t.Helper()
 39→
 40→	keepRepos := os.Getenv("E2E_KEEP_REPOS") != ""
 41→
 42→	// Always use os.MkdirTemp instead of t.TempDir(). Go's t.TempDir()
 43→	// creates nested subdirectories (TestName.../001/) whose structure
 44→	// confuses some agents' (e.g. opencode) working-directory resolution.
 45→	dir, err := os.MkdirTemp("", "e2e-repo-*")
 46→	if err != nil {
 47→		t.Fatalf("create temp dir: %v", err)
 48→	}
 49→	if keepRepos {
 50→		t.Logf("E2E_KEEP_REPOS: repo will be preserved at %s", dir)
 51→	} else {
 52→		t.Cleanup(func() { os.RemoveAll(dir) })
 53→	}
 54→
 55→	// Resolve symlinks (macOS: /var -> /private/var) so paths match
 56→	// what agent CLIs see when they resolve their own CWD.
 57→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
 58→		dir = resolved
 59→	}
 60→
 61→	Git(t, dir, "init")
 62→	Git(t, dir, "config", "user.name", "E2E Test")
 63→	Git(t, dir, "config", "user.email", "e2e@test.local")
 64→	Git(t, dir, "commit", "--allow-empty", "-m", "initial commit")
 65→
 66→	entire.Enable(t, dir, agent.EntireAgent())
 67→	PatchSettings(t, dir, map[string]any{"log_level": "debug"})
 68→
 69→	// OpenCode's non-interactive mode auto-rejects external_directory permission
 70→	// since there's no user to prompt. Write a config to allow it.
 71→	if agent.Name() == "opencode" {
 72→		cfg := `{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}}`
 73→		if key := os.Getenv("ANTHROPIC_API_KEY"); key != "" {
 74→			cfg = fmt.Sprintf(`{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}, "provider": {"anthropic": {"options": {"apiKey": %q}}}}`, key)
 75→		}
 76→		if err := os.WriteFile(filepath.Join(dir, "opencode.json"), []byte(cfg+"\n"), 0o644); err != nil {
 77→			t.Fatalf("write opencode.json: %v", err)
 78→		}
 79→	}
 80→
 81→	// Create artifact dir eagerly so console.log is written to disk
 82→	// incrementally. Even if the test is killed by a global timeout,
 83→	// partial output survives.
 84→	artDir := artifactDir(t)
 85→	consoleLog, err := os.Create(filepath.Join(artDir, "console.log"))
 86→	if err != nil {
 87→		t.Fatalf("create console.log: %v", err)
 88→	}
 89→
 90→	state := &RepoState{
 91→		Agent:            agent,
 92→		Dir:              dir,
 93→		ArtifactDir:      artDir,
 94→		HeadBefore:       GitOutput(t, dir, "rev-parse", "HEAD"),
 95→		CheckpointBefore: GitOutput(t, dir, "rev-parse", "entire/checkpoints/v1"),
 96→		ConsoleLog:       consoleLog,
 97→	}
 98→
 99→	t.Cleanup(func() {
100→		_ = consoleLog.Close()
101→		CaptureArtifacts(t, state)
102→	})
103→
104→	return state
105→}
106→
107→// ForEachAgent runs fn as a parallel subtest for every registered agent.
108→// It handles repo setup, concurrency gating, context timeout, and cleanup.
109→// The timeout is scaled by each agent's TimeoutMultiplier.
110→func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
111→	t.Helper()
112→	t.Parallel()
113→	all := agents.All()
114→	if len(all) == 0 {
115→		t.Skip("no agents registered (check E2E_AGENT filter)")
116→	}
117→	for _, agent := range all {
118→		t.Run(agent.Name(), func(t *testing.T) {
119→			s := SetupRepo(t, agent)
120→
121→			// Use the global test deadline for slot wait so we don't
122→			// skip prematurely — only bail if the whole binary is dying.
123→			slotCtx := context.Background()
124→			if deadline, ok := t.Deadline(); ok {
125→				var cancel context.CancelFunc
126→				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
127→				defer cancel()
128→			}
129→			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
130→				t.Fatalf("timed out waiting for agent slot: %v", err)
131→			}
132→			defer agents.ReleaseSlot(agent)
133→
134→			// Per-test timeout starts after slot is acquired, scaled
135→			// by the agent's multiplier (e.g. 2.5× for gemini).
136→			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
137→			ctx, cancel := context.WithTimeout(context.Background(), scaled)
138→			defer cancel()
139→			fn(t, s, ctx)
140→		})
141→	}
142→}
143→
144→// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
145→// and returns the result. If the agent reports a transient API error, the
146→// prompt is retried once after a short delay. The caller should still check err.
147→func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
148→	t.Helper()
149→	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
150→	s.logPromptResult(out)
151→
152→	if err != nil && s.Agent.IsTransientError(out, err) {
153→		t.Logf("transient API error detected, retrying in 5s: %v", err)
154→		s.ConsoleLog.WriteString("> [retry] transient error, waiting 5s...\n")
155→		select {
156→		case <-time.After(5 * time.Second):
157→		case <-ctx.Done():
158→			return out, err
159→		}
160→		out, err = s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
161→		s.logPromptResult(out)
162→	}
163→
164→	return out, err
165→}
166→
167→func (s *RepoState) logPromptResult(out agents.Output) {
168→	s.ConsoleLog.WriteString("> " + out.Command + "\n")
169→	s.ConsoleLog.WriteString("stdout:\n" + out.Stdout + "\n")
170→	s.ConsoleLog.WriteString("stderr:\n" + out.Stderr + "\n")
171→}
172→
173→// Git runs a git command in the repo and logs it to ConsoleLog.
174→func (s *RepoState) Git(t *testing.T, args ...string) {
175→	t.Helper()
176→	s.ConsoleLog.WriteString("> git " + strings.Join(args, " ") + "\n")
177→	Git(t, s.Dir, args...)
178→}
179→
180→// StartSession starts an interactive session and registers it for pane
181→// capture in artifacts. Returns nil if the agent does not support interactive
182→// mode. The session is closed automatically during test cleanup.
183→func (s *RepoState) StartSession(t *testing.T, ctx context.Context) agents.Session {
184→	t.Helper()
185→	session, err := s.Agent.StartSession(ctx, s.Dir)
186→	if err != nil {
187→		t.Fatalf("start session: %v", err)
188→	}
189→	if session == nil {
190→		return nil
191→	}
192→	s.session = session
193→	return session
194→}
195→
196→// WaitFor waits for a pattern in the interactive session's pane and logs the
197→// pane content to ConsoleLog after the wait completes (success or failure).
198→func (s *RepoState) WaitFor(t *testing.T, session agents.Session, pattern string, timeout time.Duration) {
199→	t.Helper()
200→	content, err := session.WaitFor(pattern, timeout)
201→	fmt.Fprintf(s.ConsoleLog, "> pane after WaitFor(%q):\n%s\n", pattern, content)
202→	if err != nil {
203→		t.Fatalf("WaitFor(%q): %v", pattern, err)
204→	}
205→}
206→
207→// Send sends input to an interactive session and logs it to ConsoleLog.
208→// Fails the test on error.
209→func (s *RepoState) Send(t *testing.T, session agents.Session, input string) {
210→	t.Helper()
211→	s.ConsoleLog.WriteString("> send: " + input + "\n")
212→	if err := session.Send(input); err != nil {
213→		t.Fatalf("send failed: %v", err)
214→	}
215→}
216→
217→// PatchSettings merges extra keys into .entire/settings.json.
218→func PatchSettings(t *testing.T, dir string, extra map[string]any) {
219→	t.Helper()
220→	path := filepath.Join(dir, ".entire", "settings.json")
221→	data, err := os.ReadFile(path)
222→	if err != nil {
223→		t.Fatalf("read settings: %v", err)
224→	}
225→	var settings map[string]any
226→	if err := json.Unmarshal(data, &settings); err != nil {
227→		t.Fatalf("parse settings: %v", err)
228→	}
229→	for k, v := range extra {
230→		settings[k] = v
231→	}
232→	out, err := json.MarshalIndent(settings, "", "  ")
233→	if err != nil {
234→		t.Fatalf("marshal settings: %v", err)
235→	}
236→	if err := os.WriteFile(path, out, 0o644); err != nil {
237→		t.Fatalf("write settings: %v", err)
238→	}
239→}
240→
241→// Git runs a git command in the given directory and fails the test if it
242→// returns a non-zero exit code.
243→func Git(t *testing.T, dir string, args ...string) {
244→	t.Helper()
245→
246→	cmd := exec.Command("git", args...)
247→	if dir != "" {
248→		cmd.Dir = dir
249→	}
250→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
251→
252→	out, err := cmd.CombinedOutput()
253→	if err != nil {
254→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, out)
255→	}
256→}
257→
258→// GitOutput runs a git command in the given directory, returns its trimmed
259→// stdout, and fails the test on error.
260→func GitOutput(t *testing.T, dir string, args ...string) string {
261→	t.Helper()
262→
263→	cmd := exec.Command("git", args...)
264→	if dir != "" {
265→		cmd.Dir = dir
266→	}
267→
268→	out, err := cmd.Output()
269→	if err != nil {
270→		var stderr string
271→		ee := &exec.ExitError{}
272→		if errors.As(err, &ee) {
273→			stderr = string(ee.Stderr)
274→		}
275→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, stderr)
276→	}
277→
278→	return strings.TrimSpace(string(out))
279→}
280→
281→// NewCheckpointCommits returns the SHAs of commits added to the
282→// entire/checkpoints/v1 branch since the test was set up, oldest first.
283→func NewCheckpointCommits(t *testing.T, s *RepoState) []string {
284→	t.Helper()
285→
286→	log := GitOutput(t, s.Dir, "log", "--reverse", "--format=%H", s.CheckpointBefore+"..entire/checkpoints/v1")
287→	if log == "" {
288→		return nil
289→	}
290→	return strings.Split(log, "\n")
291→}
292→
293→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
294→// checkpoint branch. It parses the two-level directory structure
295→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
296→func CheckpointIDs(t *testing.T, dir string) []string {
297→	t.Helper()
298→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
299→	if out == "" {
300→		return nil
301→	}
302→	seen := map[string]bool{}
303→	var ids []string
304→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
305→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
306→		parts := strings.Split(line, "/")
307→		if len(parts) == 3 && parts[2] == "metadata.json" {
308→			id := parts[0] + parts[1]
309→			if !seen[id] {
310→				seen[id] = true
311→				ids = append(ids, id)
312→			}
313→		}
314→	}
315→	return ids
316→}
