318→// ReadCheckpointMetadata reads the checkpoint-level metadata.json from the
319→// tip of the checkpoint branch for the given checkpoint ID.
320→func ReadCheckpointMetadata(t *testing.T, dir string, checkpointID string) CheckpointMetadata {
321→	t.Helper()
322→
323→	path := CheckpointPath(checkpointID) + "/metadata.json"
324→	blob := "entire/checkpoints/v1:" + path
325→
326→	raw := GitOutput(t, dir, "show", blob)
327→
328→	var meta CheckpointMetadata
329→	if err := json.Unmarshal([]byte(raw), &meta); err != nil {
330→		t.Fatalf("unmarshal checkpoint metadata from %s: %v", blob, err)
331→	}
332→
333→	return meta
334→}
