336→// ReadSessionMetadata reads a session's metadata.json from the tip of the
337→// checkpoint branch for the given checkpoint ID and session index.
338→func ReadSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int) SessionMetadata {
339→	t.Helper()
