341→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
342→	blob := "entire/checkpoints/v1:" + path
343→
344→	raw := GitOutput(t, dir, "show", blob)
345→
