395→	}
396→
397→	Git(t, bareDir, "init", "--bare")
398→	Git(t, s.Dir, "remote", "add", "origin", bareDir)
399→	Git(t, s.Dir, "push", "-u", "origin", "HEAD")
400→	return bareDir
401→}
