  1→package agents
  2→
  3→import (
  4→	"fmt"
  5→	"os/exec"
  6→	"regexp"
  7→	"strings"
  8→	"time"
  9→)
 10→
 11→// TmuxSession implements Session using tmux for PTY-based interactive agents.
 12→type TmuxSession struct {
 13→	name         string
 14→	stableAtSend string   // stable content snapshot when Send was last called
 15→	cleanups     []func() // run on Close
 16→}
 17→
 18→// OnClose registers a function to run when the session is closed.
 19→func (s *TmuxSession) OnClose(fn func()) {
 20→	s.cleanups = append(s.cleanups, fn)
 21→}
 22→
 23→// NewTmuxSession creates a new tmux session running the given command in dir.
 24→// unsetEnv lists environment variable names to strip from the session.
 25→func NewTmuxSession(name string, dir string, unsetEnv []string, command string, args ...string) (*TmuxSession, error) {
 26→	s := &TmuxSession{name: name}
 27→
 28→	tmuxArgs := []string{"new-session", "-d", "-s", name, "-c", dir}
 29→	// Build a shell command string, prefixed with env -u for each var to strip.
 30→	// All arguments are shell-quoted to prevent injection or splitting.
 31→	var parts []string
 32→	for _, v := range unsetEnv {
 33→		parts = append(parts, "env", "-u", shellQuote(v))
 34→	}
 35→	parts = append(parts, shellQuote(command))
 36→	for _, a := range args {
 37→		parts = append(parts, shellQuote(a))
 38→	}
 39→	tmuxArgs = append(tmuxArgs, strings.Join(parts, " "))
 40→
 41→	cmd := exec.Command("tmux", tmuxArgs...)
 42→	if out, err := cmd.CombinedOutput(); err != nil {
 43→		return nil, fmt.Errorf("tmux new-session: %w\n%s", err, out)
 44→	}
 45→	// Keep the pane around after the command exits so we can capture error output.
 46→	setCmd := exec.Command("tmux", "set-option", "-t", name, "remain-on-exit", "on")
 47→	_ = setCmd.Run()
 48→	return s, nil
 49→}
 50→
 51→func (s *TmuxSession) Send(input string) error {
 52→	s.stableAtSend = stableContent(s.Capture())
 53→	// Send text and Enter separately — Claude's TUI can swallow Enter
 54→	// if it arrives before the input handler finishes processing the text.
 55→	if err := s.SendKeys(input); err != nil {
 56→		return err
 57→	}
 58→	time.Sleep(200 * time.Millisecond)
 59→	return s.SendKeys("Enter")
 60→}
 61→
 62→// SendKeys sends raw tmux key names without appending Enter.
 63→func (s *TmuxSession) SendKeys(keys ...string) error {
 64→	args := append([]string{"send-keys", "-t", s.name}, keys...)
 65→	cmd := exec.Command("tmux", args...)
 66→	out, err := cmd.CombinedOutput()
 67→	if err != nil {
 68→		return fmt.Errorf("tmux send-keys: %w\n%s", err, out)
 69→	}
 70→	return nil
 71→}
 72→
 73→const (
 74→	settleTime   = 2 * time.Second
 75→	pollInterval = 500 * time.Millisecond
 76→)
 77→
 78→// stableContent returns the content with the last few lines stripped,
 79→// so that TUI status bar updates don't prevent the settle timer.
 80→func stableContent(content string) string {
 81→	lines := strings.Split(content, "\n")
 82→	if len(lines) > 3 {
 83→		lines = lines[:len(lines)-3]
 84→	}
 85→	return strings.Join(lines, "\n")
 86→}
 87→
 88→func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
 89→	re, err := regexp.Compile(pattern)
 90→	if err != nil {
 91→		return "", fmt.Errorf("invalid pattern: %w", err)
 92→	}
 93→
 94→	deadline := time.Now().Add(timeout)
 95→	var matchedAt time.Time
 96→	var lastStable string
 97→	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits
 98→
 99→	for time.Now().Before(deadline) {
100→		content := s.Capture()
101→		stable := stableContent(content)
102→
103→		if !re.MatchString(content) {
104→			// Pattern lost — reset
105→			matchedAt = time.Time{}
106→			lastStable = ""
107→			time.Sleep(pollInterval)
108→			continue
109→		}
110→
111→		// Detect content change since Send was called
112→		if !contentChanged && stable != s.stableAtSend {
113→			contentChanged = true
114→		}
115→
116→		if stable != lastStable {
117→			// Pattern matches but content is still changing — reset settle timer
118→			matchedAt = time.Now()
119→			lastStable = stable
120→			time.Sleep(pollInterval)
121→			continue
122→		}
123→
124→		// Pattern matches and content hasn't changed since matchedAt.
125→		// Only settle if content changed at least once after Send
126→		// (prevents false settle on echoed input before agent starts).
127→		if contentChanged && time.Since(matchedAt) >= settleTime {
128→			return content, nil
129→		}
130→
131→		time.Sleep(pollInterval)
132→	}
133→	content := s.Capture()
134→	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
135→}
136→
137→func (s *TmuxSession) Capture() string {
138→	cmd := exec.Command("tmux", "capture-pane", "-t", s.name, "-p")
139→	out, _ := cmd.Output()
140→	return strings.TrimRight(string(out), "\n")
141→}
142→
143→func (s *TmuxSession) Close() error {
144→	for _, fn := range s.cleanups {
145→		fn()
146→	}
147→	cmd := exec.Command("tmux", "kill-session", "-t", s.name)
148→	out, err := cmd.CombinedOutput()
149→	if err != nil {
150→		return fmt.Errorf("tmux kill-session: %w\n%s", err, out)
151→	}
152→	return nil
153→}
154→
155→// shellQuote wraps s in single quotes with proper escaping for POSIX shells.
156→func shellQuote(s string) string {
157→	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
158→}
