369→// AreHooksInstalled checks if Entire hooks are installed.
370→func (c *ClaudeCodeAgent) AreHooksInstalled() bool {
371→	// Use repo root to find .claude directory when run from a subdirectory
372→	repoRoot, err := paths.WorktreeRoot()
373→	if err != nil {
374→		repoRoot = "." // Fallback to CWD if not in a git repo
375→	}
376→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
377→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
378→	if err != nil {
379→		return false
380→	}
381→
382→	var settings ClaudeSettings
383→	if err := json.Unmarshal(data, &settings); err != nil {
384→		return false
385→	}
386→
387→	// Check for at least one of our hooks (new or old format)
388→	return hookCommandExists(settings.Hooks.Stop, "entire hooks claude-code stop") ||
389→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop") ||
390→		// Backwards compatibility: check for old hook formats
391→		hookCommandExists(settings.Hooks.Stop, "entire hooks claudecode stop") ||
392→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claudecode stop") ||
393→		hookCommandExists(settings.Hooks.Stop, "entire rewind claude-hook --stop") ||
394→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go rewind claude-hook --stop")
395→}
