397→// Helper functions for hook management
398→
399→func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
400→	for _, matcher := range matchers {
401→		for _, hook := range matcher.Hooks {
402→			if hook.Command == command {
403→				return true
404→			}
405→		}
406→	}
407→	return false
408→}
409→
410→func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
411→	for _, matcher := range matchers {
412→		if matcher.Matcher == matcherName {
413→			for _, hook := range matcher.Hooks {
414→				if hook.Command == command {
415→					return true
416→				}
417→			}
418→		}
419→	}
420→	return false
421→}
422→
423→func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
424→	entry := ClaudeHookEntry{
425→		Type:    "command",
426→		Command: command,
427→	}
428→
429→	// If no matcher name, add to a matcher with empty string
430→	if matcherName == "" {
431→		for i, matcher := range matchers {
432→			if matcher.Matcher == "" {
433→				matchers[i].Hooks = append(matchers[i].Hooks, entry)
434→				return matchers
435→			}
436→		}
437→		return append(matchers, ClaudeHookMatcher{
438→			Matcher: "",
439→			Hooks:   []ClaudeHookEntry{entry},
440→		})
441→	}
442→
443→	// Find or create matcher with the given name
444→	for i, matcher := range matchers {
445→		if matcher.Matcher == matcherName {
446→			matchers[i].Hooks = append(matchers[i].Hooks, entry)
447→			return matchers
448→		}
449→	}
450→
451→	return append(matchers, ClaudeHookMatcher{
452→		Matcher: matcherName,
453→		Hooks:   []ClaudeHookEntry{entry},
454→	})
455→}
456→
457→// isEntireHook checks if a command is an Entire hook (old or new format)
458→func isEntireHook(command string) bool {
459→	for _, prefix := range entireHookPrefixes {
460→		if strings.HasPrefix(command, prefix) {
461→			return true
462→		}
463→	}
464→	return false
465→}
466→
467→// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
468→func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
469→	result := make([]ClaudeHookMatcher, 0, len(matchers))
470→	for _, matcher := range matchers {
471→		filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
472→		for _, hook := range matcher.Hooks {
473→			if !isEntireHook(hook.Command) {
474→				filteredHooks = append(filteredHooks, hook)
475→			}
476→		}
477→		// Only keep the matcher if it has hooks remaining
478→		if len(filteredHooks) > 0 {
479→			matcher.Hooks = filteredHooks
480→			result = append(result, matcher)
481→		}
482→	}
483→	return result
484→}
485→
486→// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
487→// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task", "TodoWrite")
488→func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
489→	// Same logic as removeEntireHooks - both work on the same structure
490→	return removeEntireHooks(matchers)
491→}
