217→// PatchSettings merges extra keys into .entire/settings.json.
218→func PatchSettings(t *testing.T, dir string, extra map[string]any) {
219→	t.Helper()
220→	path := filepath.Join(dir, ".entire", "settings.json")
221→	data, err := os.ReadFile(path)
222→	if err != nil {
223→		t.Fatalf("read settings: %v", err)
224→	}
225→	var settings map[string]any
226→	if err := json.Unmarshal(data, &settings); err != nil {
227→		t.Fatalf("parse settings: %v", err)
228→	}
229→	for k, v := range extra {
230→		settings[k] = v
231→	}
232→	out, err := json.MarshalIndent(settings, "", "  ")
233→	if err != nil {
234→		t.Fatalf("marshal settings: %v", err)
235→	}
236→	if err := os.WriteFile(path, out, 0o644); err != nil {
237→		t.Fatalf("write settings: %v", err)
238→	}
239→}
