258→// GitOutput runs a git command in the given directory, returns its trimmed
259→// stdout, and fails the test on error.
260→func GitOutput(t *testing.T, dir string, args ...string) string {
261→	t.Helper()
262→
263→	cmd := exec.Command("git", args...)
264→	if dir != "" {
265→		cmd.Dir = dir
266→	}
267→
268→	out, err := cmd.Output()
269→	if err != nil {
270→		var stderr string
271→		ee := &exec.ExitError{}
272→		if errors.As(err, &ee) {
273→			stderr = string(ee.Stderr)
274→		}
275→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, stderr)
276→	}
277→
278→	return strings.TrimSpace(string(out))
279→}
