380→// SetupBareRemote creates a bare git repo, adds it as "origin", and pushes
381→// the initial commit. Returns the bare repo path.
382→func SetupBareRemote(t *testing.T, s *RepoState) string {
383→	t.Helper()
384→
385→	var bareDir string
386→	if os.Getenv("E2E_KEEP_REPOS") != "" {
387→		var err error
388→		bareDir, err = os.MkdirTemp("", "e2e-bare-*")
389→		if err != nil {
390→			t.Fatalf("create bare remote dir: %v", err)
391→		}
392→		t.Logf("E2E_KEEP_REPOS: bare remote will be preserved at %s", bareDir)
393→	} else {
394→		bareDir = t.TempDir()
395→	}
396→
397→	Git(t, bareDir, "init", "--bare")
398→	Git(t, s.Dir, "remote", "add", "origin", bareDir)
399→	Git(t, s.Dir, "push", "-u", "origin", "HEAD")
400→	return bareDir
401→}
