 70→func (c *Claude) IsTransientError(out Output, err error) bool {
 71→	if err == nil {
 72→		return false
 73→	}
 74→	combined := out.Stdout + out.Stderr
 75→	transientPatterns := []string{
 76→		"overloaded",
 77→		"rate limit",
 78→		"529",
 79→		"503",
 80→		"ECONNRESET",
 81→		"ETIMEDOUT",
 82→	}
 83→	for _, p := range transientPatterns {
