 91→func (c *Claude) Bootstrap() error {
 92→	// On CI, write a config file so Claude Code uses the API key from the
 93→	// environment instead of trying OAuth/Keychain.
 94→	if os.Getenv("CI") == "" {
 95→		return nil
 96→	}
 97→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
 98→	if apiKey == "" {
 99→		return nil
100→	}
101→	home, err := os.UserHomeDir()
102→	if err != nil {
103→		return fmt.Errorf("get home dir: %w", err)
104→	}
105→	dir := filepath.Join(home, ".claude")
106→	if err := os.MkdirAll(dir, 0o755); err != nil {
107→		return fmt.Errorf("mkdir %s: %w", dir, err)
108→	}
109→	config := fmt.Sprintf(`{"primaryApiKey":%q,"hasCompletedOnboarding":true}`, apiKey)
110→	path := filepath.Join(dir, ".claude.json")
111→	return os.WriteFile(path, []byte(config), 0o644)
112→}
