114→func (c *Claude) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
115→	cfg := &runConfig{Model: "haiku"}
116→	for _, o := range opts {
117→		o(cfg)
118→	}
119→
120→	configDir, err := cleanConfigDir()
121→	if err != nil {
122→		return Output{}, fmt.Errorf("create clean config dir: %w", err)
123→	}
124→	defer func() { _ = os.RemoveAll(configDir) }()
125→
126→	env := append(cleanEnv(),
127→		"ACCESSIBLE=1",
128→		"ENTIRE_TEST_TTY=0",
129→
130→		// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
131→		// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
132→		// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
133→		// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
134→		// itself, clone its plugins, etc.
135→		"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
136→		"CLAUDE_CONFIG_DIR="+configDir,
137→	)
138→
139→	args := []string{"-p", prompt, "--model", cfg.Model, "--dangerously-skip-permissions"}
140→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--dangerously-skip-permissions"}
141→	cmd := exec.CommandContext(ctx, c.Binary(), args...)
142→	cmd.Dir = dir
143→	cmd.Stdin = nil
144→	cmd.Env = env
145→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
146→	cmd.Cancel = func() error {
147→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
148→	}
149→	cmd.WaitDelay = 5 * time.Second
150→
151→	var stdout, stderr strings.Builder
152→	cmd.Stdout = &stdout
153→	cmd.Stderr = &stderr
154→
155→	err = cmd.Run()
156→	exitCode := 0
157→	if err != nil {
158→		exitErr := &exec.ExitError{}
159→		if errors.As(err, &exitErr) {
160→			exitCode = exitErr.ExitCode()
161→		} else {
162→			exitCode = -1
163→		}
164→	}
165→
166→	return Output{
167→		Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
168→		Stdout:   stdout.String(),
169→		Stderr:   stderr.String(),
170→		ExitCode: exitCode,
171→	}, err
172→}
173→
174→func (c *Claude) StartSession(ctx context.Context, dir string) (Session, error) {
175→	name := fmt.Sprintf("claude-test-%d", time.Now().UnixNano())
176→
177→	configDir, err := cleanConfigDir()
178→	if err != nil {
179→		return nil, fmt.Errorf("create clean config dir: %w", err)
180→	}
181→
182→	envArgs := []string{
183→		"ACCESSIBLE=1",
184→		"ENTIRE_TEST_TTY=0",
185→
186→		// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
187→		// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
188→		// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
189→		// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
190→		// itself, clone its plugins, etc.
191→		"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
192→		"CLAUDE_CONFIG_DIR=" + configDir,
193→	}
194→
195→	args := append([]string{"env"}, envArgs...)
196→	args = append(args, c.Binary(), "--dangerously-skip-permissions")
197→	s, err := NewTmuxSession(name, dir, []string{"CLAUDECODE"}, args[0], args[1:]...)
198→	if err != nil {
199→		_ = os.RemoveAll(configDir)
200→		return nil, err
201→	}
202→	s.OnClose(func() { _ = os.RemoveAll(configDir) })
203→
204→	// Dismiss startup dialogs until we reach the input prompt.
205→	for range 5 {
206→		content, err := s.WaitFor(`❯`, 15*time.Second)
207→		if err != nil {
208→			_ = s.Close()
209→			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
210→		}
211→		if !strings.Contains(content, "Enter to confirm") {
212→			break
213→		}
214→		// The bypass permissions dialog defaults to "No, exit" —
215→		// arrow down to "Yes, I accept" before confirming.
216→		if strings.Contains(content, "Yes, I accept") {
217→			_ = s.SendKeys("Down")
218→			time.Sleep(200 * time.Millisecond)
219→		}
220→		_ = s.SendKeys("Enter")
221→		time.Sleep(500 * time.Millisecond)
222→	}
223→	s.stableAtSend = ""
224→
225→	return s, nil
226→}
