 7→
 8→type Output struct {
 9→	Command  string
10→	Stdout   string
11→	Stderr   string
12→	ExitCode int
13→}
14→
15→type Option func(*runConfig)
16→type runConfig struct {
17→	Model          string
18→	PermissionMode string
19→}
20→
21→func WithModel(model string) Option {
22→	return func(c *runConfig) { c.Model = model }
23→}
24→
25→func WithPermissionMode(mode string) Option {
26→	return func(c *runConfig) { c.PermissionMode = mode }
27→}
28→
29→type Agent interface {
30→	Name() string
31→	// Binary returns the CLI binary name (e.g. "claude", "gemini").
32→	Binary() string
33→	EntireAgent() string
34→	PromptPattern() string
35→	// TimeoutMultiplier returns a factor applied to per-test timeouts.
36→	// Slower agents (e.g. Gemini) return values > 1.
37→	TimeoutMultiplier() float64
38→	RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error)
39→	StartSession(ctx context.Context, dir string) (Session, error)
40→	// Bootstrap performs one-time CI setup (auth config, warmup, etc.).
41→	// Called before any tests run. Implementations should be idempotent.
42→	Bootstrap() error
43→	// IsTransientError returns true if the error from RunPrompt looks like
44→	// a transient API failure (e.g. 500, rate limit, network error) that
45→	// is worth retrying.
46→	IsTransientError(out Output, err error) bool
47→}
48→
49→type Session interface {
50→	Send(input string) error
51→	WaitFor(pattern string, timeout time.Duration) (string, error)
52→	Capture() string
53→	Close() error
54→}
55→
56→var registry []Agent
57→var gates = map[string]chan struct{}{}
58→
59→func Register(a Agent) {
60→	registry = append(registry, a)
61→}
62→
63→// RegisterGate sets a concurrency limit for an agent's tests.
64→// Tests call AcquireSlot/ReleaseSlot to respect this limit.
65→func RegisterGate(name string, max int) {
66→	gates[name] = make(chan struct{}, max)
67→}
68→
69→// AcquireSlot blocks until a test slot is available for the agent or the
70→// context is cancelled. Returns a non-nil error if the context expires
71→// before a slot opens.
72→func AcquireSlot(ctx context.Context, a Agent) error {
73→	g, ok := gates[a.Name()]
74→	if !ok {
75→		return nil
76→	}
77→	select {
78→	case g <- struct{}{}:
79→		return nil
80→	case <-ctx.Done():
81→		return ctx.Err()
82→	}
83→}
84→
85→// ReleaseSlot frees a test slot for the agent.
86→func ReleaseSlot(a Agent) {
87→	if g, ok := gates[a.Name()]; ok {
88→		<-g
89→	}
90→}
91→
92→func All() []Agent {
93→	return registry
94→}
