	// it checks both in isHeadlessMode() and skips interactive TUI entirely.
	s, err := NewTmuxSession(name, dir, []string{"CI", "GITHUB_ACTIONS"}, "env", "ACCESSIBLE=1", "ENTIRE_TEST_TTY=0", g.Binary(), "--model", geminiDefaultModel, "-y")
