			slog.String("checkpoint_type", "session"),
			slog.Int("checkpoint_count", state.StepCount),
			slog.String("shadow_branch", shadowBranchName),
		)
		fmt.Fprintf(os.Stderr, "Skipped checkpoint (no changes since last checkpoint)\n")
		return nil
	}

	// Update session state
	state.StepCount++

	// Note: LastCheckpointID is intentionally NOT cleared here.
	// It is set during condensation and used by handleAmendCommitMsg
	// to restore checkpoint trailers on amend operations.

	// Store the prompt attribution we calculated before saving
	state.PromptAttributions = append(state.PromptAttributions, promptAttr)

	// Track touched files (modified, new, and deleted)
	state.FilesTouched = mergeFilesTouched(state.FilesTouched, ctx.ModifiedFiles, ctx.NewFiles, ctx.DeletedFiles)

	// On first checkpoint, record the transcript identifier for this session
	if state.StepCount == 1 {
		state.TranscriptIdentifierAtStart = ctx.StepTranscriptIdentifier
	}

	// Accumulate token usage
	if ctx.TokenUsage != nil {
		state.TokenUsage = accumulateTokenUsage(state.TokenUsage, ctx.TokenUsage)
	}

	// Save updated state
	if err := s.saveSessionState(state); err != nil {
		return fmt.Errorf("failed to save session state: %w", err)
	}

	if !branchExisted {
		fmt.Fprintf(os.Stderr, "Created shadow branch '%s' and committed changes\n", shadowBranchName)
	} else {
		fmt.Fprintf(os.Stderr, "Committed changes to shadow branch '%s'\n", shadowBranchName)
	}

	// Log checkpoint creation
	logCtx := logging.WithComponent(context.Background(), "checkpoint")
	logging.Info(logCtx, "checkpoint saved",
		slog.String("strategy", "manual-commit"),
		slog.String("checkpoint_type", "session"),
		slog.Int("checkpoint_count", state.StepCount),
		slog.Int("modified_files", len(ctx.ModifiedFiles)),
		slog.Int("new_files", len(ctx.NewFiles)),
		slog.Int("deleted_files", len(ctx.DeletedFiles)),
		slog.String("shadow_branch", shadowBranchName),
		slog.Bool("branch_created", !branchExisted),
	)

	return nil
}

// SaveTaskStep saves a task step checkpoint to the shadow branch.
// Uses checkpoint.GitStore.WriteTemporaryTask for git operations.
func (s *ManualCommitStrategy) SaveTaskStep(ctx TaskStepContext) error {
	repo, err := OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Load session state
	state, err := s.loadSessionState(ctx.SessionID)
	if err != nil || state == nil || state.BaseCommit == "" {
		agentType := resolveAgentType(ctx.AgentType, state)
		state, err = s.initializeSession(repo, ctx.SessionID, agentType, "", "") // No transcript/prompt in fallback
		if err != nil {

}

// Get checkpoint store
store, err := s.getCheckpointStore()
if err != nil {
	return fmt.Errorf("failed to get checkpoint store: %w", err)
}

// Check if shadow branch exists to report whether we created it
shadowBranchName := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
branchExisted := store.ShadowBranchExists(state.BaseCommit, state.WorktreeID)

// Use the pending attribution calculated at prompt start (in InitializeSession)
// This was calculated BEFORE the agent made changes, so it accurately captures user edits
var promptAttr PromptAttribution
if state.PendingPromptAttribution != nil {
	promptAttr = *state.PendingPromptAttribution
	state.PendingPromptAttribution = nil // Clear after use
} else {
	// No pending attribution (e.g., first checkpoint or session initialized without it)
	promptAttr = PromptAttribution{CheckpointNumber: state.StepCount + 1}
}

// Log the prompt attribution for debugging
attrLogCtx := logging.WithComponent(context.Background(), "attribution")
logging.Debug(attrLogCtx, "prompt attribution at checkpoint save",
	slog.Int("checkpoint_number", promptAttr.CheckpointNumber),
	slog.Int("user_added", promptAttr.UserLinesAdded),
	slog.Int("user_removed", promptAttr.UserLinesRemoved),
	slog.Int("agent_added", promptAttr.AgentLinesAdded),
	slog.Int("agent_removed", promptAttr.AgentLinesRemoved),
	slog.String("session_id", sessionID))

// Use WriteTemporary to create the checkpoint
isFirstCheckpointOfSession := state.StepCount == 0
result, err := store.WriteTemporary(context.Background(), checkpoint.WriteTemporaryOptions{
	SessionID:         sessionID,
	BaseCommit:        state.BaseCommit,
	WorktreeID:        state.WorktreeID,
	ModifiedFiles:     ctx.ModifiedFiles,
	NewFiles:          ctx.NewFiles,
	DeletedFiles:      ctx.DeletedFiles,
	MetadataDir:       ctx.MetadataDir,
	MetadataDirAbs:    ctx.MetadataDirAbs,
	CommitMessage:     ctx.CommitMessage,
	AuthorName:        ctx.AuthorName,
	AuthorEmail:       ctx.AuthorEmail,
	IsFirstCheckpoint: isFirstCheckpointOfSession,
})
if err != nil {
	return fmt.Errorf("failed to write temporary checkpoint: %w", err)
}

// If checkpoint was skipped due to deduplication (no changes), return early
if result.Skipped {

	newHead := head.Hash().String()

	// Pre-resolve HEAD tree and parent tree once for the entire PostCommit.
	// These are immutable within this hook invocation and used by multiple
	// per-session functions (filesChangedInCommit, filesOverlapWithContent,
	// filesWithRemainingAgentChanges, calculateSessionAttributions).
	var headTree *object.Tree
	if t, err := commit.Tree(); err == nil {
		headTree = t
	}
	var parentTree *object.Tree
	if commit.NumParents() > 0 {
		if parent, err := commit.Parent(0); err == nil {
			if t, err := parent.Tree(); err == nil {
				parentTree = t
			}
		}
	}

	committedFileSet := filesChangedInCommit(commit, headTree, parentTree)

	for _, state := range sessions {
		s.postCommitProcessSession(logCtx, repo, state, &transitionCtx, checkpointID,
			head, commit, newHead, headTree, parentTree, committedFileSet,
			shadowBranchesToDelete, uncondensedActiveOnBranch)
	}

	// Clean up shadow branches — only delete when ALL sessions on the branch are non-active
	// or were condensed during this PostCommit.
	for shadowBranchName := range shadowBranchesToDelete {
		if uncondensedActiveOnBranch[shadowBranchName] {
			logging.Debug(logCtx, "post-commit: preserving shadow branch (active session exists)",
				slog.String("shadow_branch", shadowBranchName),
			)
			continue
		}
		if err := deleteShadowBranch(repo, shadowBranchName); err != nil {
			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to clean up %s: %v\n", shadowBranchName, err)
		} else {
			fmt.Fprintf(os.Stderr, "[entire] Cleaned up shadow branch: %s\n", shadowBranchName)
			logging.Info(logCtx, "shadow branch deleted",
				slog.String("strategy", "manual-commit"),
				slog.String("shadow_branch", shadowBranchName),
			)
		}
	}

	return nil
}

// postCommitProcessSession handles a single session within the PostCommit loop.
// Pre-resolved git objects (headTree, parentTree) are shared across all sessions;
// per-session shadow ref/tree are resolved once here and threaded through sub-calls.
func (s *ManualCommitStrategy) postCommitProcessSession(
	logCtx context.Context,
	repo *git.Repository,
	state *SessionState,
	transitionCtx *session.TransitionContext,
	checkpointID id.CheckpointID,
	head *plumbing.Reference,
	commit *object.Commit,
	newHead string,
	headTree, parentTree *object.Tree,
	committedFileSet map[string]struct{},
	shadowBranchesToDelete map[string]struct{},
	uncondensedActiveOnBranch map[string]bool,
) {
	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)

	// Pre-resolve shadow branch ref and tree for this session.
	// These are read 4+ times across sessionHasNewContent, filesOverlapWithContent,
	// CondenseSession, filesWithRemainingAgentChanges, and calculateSessionAttributions.
	var shadowRef *plumbing.Reference
	var shadowTree *object.Tree
	if ref, refErr := repo.Reference(plumbing.NewBranchReferenceName(shadowBranchName), true); refErr == nil {
		shadowRef = ref
		if sc, scErr := repo.CommitObject(ref.Hash()); scErr == nil {
			if st, stErr := sc.Tree(); stErr == nil {
				shadowTree = st
			}
		}
	}

	// Check for new content (needed for TransitionContext and condensation).
	// Fail-open: if content check errors, assume new content exists so we
	// don't silently skip data that should have been condensed.
	//
	// For ACTIVE sessions: the commit has a checkpoint trailer (verified above),
	// meaning PrepareCommitMsg already determined this commit is session-related.
	// The trailer is only added when either:
	//   - No TTY (agent/subagent committing) — added unconditionally
	//   - TTY (human committing) — added after content detection confirmed agent work
	// In both cases, PrepareCommitMsg already validated this commit. We trust
	// that decision here. Transcript-based re-validation is unreliable because
	// subagent transcripts may not be available yet (subagent still running).
	var hasNew bool
	if state.Phase.IsActive() {
		hasNew = true
	} else {
		var contentErr error
		hasNew, contentErr = s.sessionHasNewContent(repo, state, shadowTree)
		if contentErr != nil {
			hasNew = true
			logging.Debug(logCtx, "post-commit: error checking session content, assuming new content",
				slog.String("session_id", state.SessionID),
				slog.String("error", contentErr.Error()),
			)
		}
	}
	transitionCtx.HasFilesTouched = len(state.FilesTouched) > 0

	// Save FilesTouched BEFORE TransitionAndLog — the handler's condensation
	// clears it, but we need the original list for carry-forward computation.
	// For mid-session commits (ACTIVE, no shadow branch), state.FilesTouched may be empty
	// because no SaveStep/Stop has been called yet. Extract files from transcript.
	filesTouchedBefore := make([]string, len(state.FilesTouched))
	copy(filesTouchedBefore, state.FilesTouched)
	if len(filesTouchedBefore) == 0 && state.Phase.IsActive() && state.TranscriptPath != "" {
		filesTouchedBefore = s.extractFilesFromLiveTranscript(state)

