package entire

import (
	"encoding/json"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"sync"
	"testing"
)

var (
	buildOnce sync.Once
	binPath   string
)

// BinPath returns the path to the entire binary. On first call it checks
// E2E_ENTIRE_BIN; if unset it builds the binary from source. Fatal on failure.
func BinPath() string {
	buildOnce.Do(resolveBin)
	return binPath
}

func resolveBin() {
	if p := os.Getenv("E2E_ENTIRE_BIN"); p != "" {
		binPath = p
		return
	}

	// Build from source. Find module root relative to this source file.
	_, thisFile, _, ok := runtime.Caller(0)
	if !ok {
		log.Fatal("entire: cannot determine source file path")
	}
	// thisFile = .../cli/e2e/entire/entire.go → module root = .../cli/
	moduleRoot := filepath.Join(filepath.Dir(thisFile), "..", "..")

	tmpDir, err := os.MkdirTemp("", "entire-e2e-*")
	if err != nil {
		log.Fatalf("entire: create temp dir: %v", err)
	}

	bin := filepath.Join(tmpDir, "entire")
	cmd := exec.Command("go", "build", "-o", bin, "./cmd/entire")
	cmd.Dir = moduleRoot
	out, err := cmd.CombinedOutput()
	if err != nil {
		log.Fatalf("entire: build from source: %v\n%s", err, out)
	}
	binPath = bin
}

// RewindPoint represents a single entry from `entire rewind --list`.
type RewindPoint struct {
	ID             string `json:"id"`
	Message        string `json:"message"`
	MetadataDir    string `json:"metadata_dir"`
	Date           string `json:"date"`
	IsLogsOnly     bool   `json:"is_logs_only"`
	CondensationID string `json:"condensation_id"`
	SessionID      string `json:"session_id"`
}

// Enable runs `entire enable` for the given agent with telemetry disabled.
func Enable(t *testing.T, dir, agent string) {
	t.Helper()
	run(t, dir, "enable", "--agent", agent, "--telemetry=false")
}

// Disable runs `entire disable` in the given directory.
func Disable(t *testing.T, dir string) {
	t.Helper()
	run(t, dir, "disable")
}

// RewindList runs `entire rewind --list` and parses the JSON output.
func RewindList(t *testing.T, dir string) []RewindPoint {
	t.Helper()
	out := run(t, dir, "rewind", "--list")

	var points []RewindPoint
	if err := json.Unmarshal([]byte(out), &points); err != nil {
		t.Fatalf("parse rewind list: %v\nraw output: %s", err, out)
	}
	return points
}

// Rewind runs `entire rewind --to <id>`. Returns an error instead of
// failing the test, since callers may test failure cases.
func Rewind(t *testing.T, dir, id string) error {
