144→const (
145→	transientRetryAttempts    = 3
146→	transientRetryInitBackoff = 1 * time.Second
147→)
148→
149→// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
150→// and returns the result. If the agent reports a transient API error, the
151→// prompt is retried up to transientRetryAttempts times with exponential
152→// backoff. The caller should still check err.
153→func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
154→	t.Helper()
155→	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
156→	s.logPromptResult(out)
157→
158→	backoff := transientRetryInitBackoff
159→	for attempt := range transientRetryAttempts {
160→		if !s.Agent.IsTransientError(out, err) {
161→			break
162→		}
163→		t.Logf("transient API error (attempt %d/%d), retrying in %s: %v", attempt+1, transientRetryAttempts, backoff, err)
164→		fmt.Fprintf(s.ConsoleLog, "> [retry %d/%d] transient error, waiting %s...\n", attempt+1, transientRetryAttempts, backoff)
165→		select {
166→		case <-time.After(backoff):
167→		case <-ctx.Done():
168→			return out, err
169→		}
170→		backoff *= 2
171→		out, err = s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
172→		s.logPromptResult(out)
173→	}
174→
175→	return out, err
176→}
177→
178→func (s *RepoState) logPromptResult(out agents.Output) {
179→	s.ConsoleLog.WriteString("> " + out.Command + "\n")
180→	s.ConsoleLog.WriteString("stdout:\n" + out.Stdout + "\n")
181→	s.ConsoleLog.WriteString("stderr:\n" + out.Stderr + "\n")
182→}
