304→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
305→// checkpoint branch. It parses the two-level directory structure
306→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
307→func CheckpointIDs(t *testing.T, dir string) []string {
308→	t.Helper()
309→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
310→	if out == "" {
311→		return nil
312→	}
313→	seen := map[string]bool{}
314→	var ids []string
315→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
316→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
317→		parts := strings.Split(line, "/")
318→		if len(parts) == 3 && parts[2] == "metadata.json" {
319→			id := parts[0] + parts[1]
320→			if !seen[id] {
321→				seen[id] = true
322→				ids = append(ids, id)
323→			}
324→		}
325→	}
326→	return ids
327→}
