365→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
366→// branch for the given checkpoint ID and session index, then returns it.
367→// This handles the race where the checkpoint branch advances before session
368→// metadata is fully committed.
369→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
370→	t.Helper()
371→
372→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
373→	blob := "entire/checkpoints/v1:" + path
374→
375→	deadline := time.Now().Add(timeout)
376→	for time.Now().Before(deadline) {
377→		raw := gitOutputSafe(dir, "show", blob)
378→		if raw != "" {
379→			var meta SessionMetadata
380→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
381→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
382→			}
383→			return meta
384→		}
385→		time.Sleep(500 * time.Millisecond)
386→	}
387→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
388→	return SessionMetadata{}
